import{_ as r,l,o as e,c as s,v as i,p as n,x as t,d,i as A,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"WiFi 6 / 7 与 OFDMA","description":"","frontmatter":{"title":"WiFi 6 / 7 与 OFDMA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wifi6-ofdma.md","filePath":"cs/wifi6-ofdma.md","lastUpdated":1789023840000}'),E={name:"cs/wifi6-ofdma.md"};function h(c,a,S,f,B,m){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="wifi-6-7-与-ofdma" tabindex="-1">WiFi 6 / 7 与 OFDMA <a class="header-anchor" href="#wifi-6-7-与-ofdma" aria-label="Permalink to &quot;WiFi 6 / 7 与 OFDMA&quot;">​</a></h1><div class="epigraph"><p>OFDMA 把一次 TXOP 切成资源单元分给多个站点，降低争用；Wi‑Fi 7 再加多链路与 4K-QAM，仍在 802.11 MAC 里。</p><footer>—— 据 IEEE 802.11ax；IEEE 802.11be 草案条款整理</footer></div><p><a href="/cs/mimo-rate-adaptation">上一课</a> 一站点占满整段 OFDM 符号。密集 BSS 里争用主导延迟。缺口是 <strong>OFDMA</strong>：AP 当调度器，把子载波组（RU）分给不同 STA，上/下行都可。本课不把蓝牙跳频写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DCF 下站点越多碰撞越多，MCS 再高也被队列与退避吃掉。11ax：触发帧启动上行 OFDMA，站点在指定 RU 发；下行同样按 RU 复用。这是把蜂窝里的调度借到 ISM 频段，仍无牌照、仍要听信道。Wi‑Fi 7（11be）：320 MHz、MLO 多链路聚合、4096-QAM——又一次在 \\(C\\) 下加压，对 SNR 与干扰更苛刻。</p><p>不要把 OFDMA 写成 5G 核心网：没有切片 SLA，只有 BSS 内调度。</p><p><span class="marginnote">802.11ax 引入 RU、BSS coloring。11be 的 MLO 与以太网 LACP 同类：多链路绑一条逻辑，但是空中。标准仍在演进，本课钉对象不钉某年芯片。</span></p><h3 id="ap-调度不是-5g-核心" tabindex="-1">AP 调度不是 5G 核心 <a class="header-anchor" href="#ap-调度不是-5g-核心" aria-label="Permalink to &quot;AP 调度不是 5G 核心&quot;">​</a></h3><p>RU 在一次 TXOP 里服务多站点，仍无牌照切片 SLA。Wi‑Fi 7 加压带宽与多链路，对 SNR 更苛刻。监管功率限制真实 \\(B\\)。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：AP 调度 → RU 分配 → 多 STA 同符号。对照 CSMA：调度减少随机接入，不等于消除隐藏节点。MLO：一条链路上 MCS 差可走另一条，类似自适应但跨频段。</p>',11)),(e(),n(p,null,{default:t(()=>[A(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AP%5B%22AP%20%E8%B0%83%E5%BA%A6%22%5D%20--%3E%20RU%5B%22%E8%B5%84%E6%BA%90%E5%8D%95%E5%85%83%22%5D%0A%20%20RU%20--%3E%20S1%5B%22%E7%AB%99%E7%82%B9%20A%22%5D%0A%20%20RU%20--%3E%20S2%5B%22%E7%AB%99%E7%82%B9%20B%22%5D%0A%20%20MLO%5B%22%E5%A4%9A%E9%93%BE%E8%B7%AF%22%5D%20--%3E%20LOG%5B%22%E4%B8%80%E6%9D%A1%E9%80%BB%E8%BE%91%E8%BF%9E%E6%8E%A5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有线 HOL 是结构；无线 HOL 常是整块信道被一个 STA 占满——OFDMA 对症。速率自适应仍按 RU 的 SNR 做。与 PFC 无关。主干 VLAN 可在 AP 上映射 SSID，不改 OFDMA。</p><p>BSS coloring：同频邻 BSS 可空间复用，干扰当噪声进 SNR。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Wi‑Fi 与 5G 融合的全部 3GPP 附录。蓝牙与 BLE 是下一课。后课默认：11ax 起 AP 可按 RU 多用户复用。</p><p>监管功率与 DFS 雷达仍限制真实 \\(B\\)，标准表不是室内承诺。</p><p>上一课留下的缺口在本课收口；「WiFi 6 / 7 与 OFDMA」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/bluetooth-ble">蓝牙与 BLE</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OFDMA 用 RU 在一次发送里服务多站点。</li><li>Wi‑Fi 7 加压带宽、星座与多链路。</li><li>仍是 802.11 争用+调度，不是运营商核心网。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.11ax；802.11be。</li></ul>',10))])}const F=r(E,[["render",h]]);export{D as __pageData,F as default};
